-- Isolated H2 fixture, never used to migrate MySQL.
CREATE TABLE app_config (app_id VARCHAR(32) PRIMARY KEY,settings_json CLOB NOT NULL,version INT NOT NULL,updated_at_ms BIGINT NOT NULL);
CREATE TABLE compression_record (id VARCHAR(64) PRIMARY KEY,app_id VARCHAR(32) NOT NULL,file_key CLOB NOT NULL,file_key_hash CHAR(64) NOT NULL,evidence_source VARCHAR(8) NOT NULL,status VARCHAR(16) NOT NULL,record_json CLOB NOT NULL,version INT NOT NULL,idempotency_key_hash CHAR(64) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,created_at_ms BIGINT NOT NULL,updated_at_ms BIGINT NOT NULL,UNIQUE(app_id,file_key_hash,evidence_source));
CREATE TABLE notification_delivery (id VARCHAR(64) PRIMARY KEY,app_id VARCHAR(32) NOT NULL,run_id VARCHAR(128),type VARCHAR(16) NOT NULL,purpose VARCHAR(16) NOT NULL,evidence_source VARCHAR(8) NOT NULL,destination_id VARCHAR(128) NOT NULL,business_key_hash CHAR(64) NOT NULL UNIQUE,idempotency_key_hash CHAR(64) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,status VARCHAR(16) NOT NULL,record_json CLOB NOT NULL,attempt_count INT NOT NULL,next_attempt_at_ms BIGINT NOT NULL,created_at_ms BIGINT NOT NULL,updated_at_ms BIGINT NOT NULL,sent_at_ms BIGINT);
